import { secureRandomBytes } from "@/lib/random";

/*
 * The `verification_code` of a crypto account: a random integer between `1000` and
 * `9999`, sent as a string. Exactly 4 digits, no leading zero. Not generated by the server: the
 * app draws it, from secureRandomBytes (AGENTS.md: never Math.random). For a Lightning account
 * validated by the 1-sat invoice, the code proves nothing, but the account is not created
 * without one.
 */

const LOWEST = 1000;
/** 1000 to 9999: 9000 values. */
const SPAN = 9000;
/** The largest multiple of SPAN within 16 bits: draws above it are drawn again, without bias. */
const LIMIT = Math.floor(65536 / SPAN) * SPAN;

/** A new code, "1000" to "9999". `random` is the tests'. */
export function newVerificationCode(random: (length: number) => Uint8Array = secureRandomBytes) {
  for (;;) {
    const bytes = random(2);
    const value = (bytes[0]! << 8) | bytes[1]!;
    if (value < LIMIT) return String(LOWEST + (value % SPAN));
  }
}

/** Whether `code` is one Mt Pelerin accepts. */
export function isVerificationCode(code: unknown): code is string {
  return typeof code === "string" && /^[1-9][0-9]{3}$/.test(code);
}
